<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/config.php';checkSession();if($_SESSION['user_role']!==ROLE_CONTADOR){exit('Acceso no autorizado.');}$r=getRecord("SELECT p.*,u.nombre,u.apellido,r.nombre_rol FROM pagos_nomina p JOIN empleados_nomina e ON e.id_empleado_nomina=p.id_empleado_nomina JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN roles r ON r.id_rol=u.id_rol WHERE p.id_pago_nomina=?",[(int)($_GET['id']??0)]);if(!$r)exit('Comprobante no encontrado.');?><!doctype html><meta charset="UTF-8"><title>Comprobante de nómina</title><style>body{font:16px Arial;margin:40px;color:#173d20}.card{max-width:680px;margin:auto;border:2px solid #2e7d32;padding:35px}.head{border-bottom:2px solid #2e7d32;margin-bottom:25px}.total{font-size:25px;font-weight:bold;color:#1f5d2a}@media print{button{display:none}}</style><div class="card"><div class="head"><h1>Clínica Dental Mi Sonrisa Feliz</h1><p>Comprobante de pago de nómina</p></div><p><b>Empleado:</b> <?=displayText($r['nombre'].' '.$r['apellido'])?></p><p><b>Cargo:</b> <?=displayText($r['nombre_rol'])?></p><p><b>Período:</b> <?=displayText($r['periodo'])?></p><p><b>Método:</b> <?=displayText($r['metodo_pago'])?></p><p><b>Fecha de pago:</b> <?=displayText($r['fecha_pago'])?></p><p class="total">Monto pagado: $<?=number_format($r['monto'],2)?></p><button onclick="print()">Imprimir comprobante</button></div>
